module rsa_decryption #(parameter public_k = 7, private_k = 3, mod = 33)(
    input clk, rst,
    input [31:0] encrypted_message,   
    output reg [31:0] decrypted_message // Encrypted/Decrypted result
    );

    /////////// POW(M,N) OPERATION /////////////
    reg [63:0] base;        
    reg [63:0] exponent;    
    reg [63:0] intermediate; 
    wire [127:0] product;  

    pipe multiplier (
        .a(intermediate),
        .b(base),
        .s(product)
    );
    // Mod encryption
    
    wire hard_message;
    assign hard_message = encrypted_message;
    
    reg [2:0] state;
    always @(posedge clk) begin
        if (rst) begin
            decrypted_message <= 32'd1;        
            intermediate <= encrypted_message; 
            base <= encrypted_message;              
            exponent <= private_k;          
            state <= 2'd0;         
        end else begin
            case (state)
                2'd0: begin
                    if (exponent > 0) begin
                        state <= 2'd1;
                    end else begin
                        decrypted_message <= intermediate; // Handle m^0 = 1
                        state <= 2'd2;
                    end
                end

                2'd1: begin
                    intermediate <= product;  // Update intermediate result
                    exponent <= exponent - 1; // Decrease exponent
                    if (exponent == 2) begin
                        decrypted_message <= product; // Final result
                        state <= 2'd2;
                    end
                end

                2'd2: begin
                    // Stay in this state after computation
                    decrypted_message <= decrypted_message % mod;
                end

            endcase
        end
    end
    
endmodule

